import { useState } from "react";
import "./App.css";

const question = {
  text: "Which planet has the most moons?",
  options: ["Jupiter", "Saturn", "Neptune"],
  answer: "Saturn",
};

export default function App() {
  // The option the player picked, or null before they answer
  const [picked, setPicked] = useState(null);

  // 1. Work out whether they've answered, and whether they were right
  const answered = picked !== null;
  const correct = picked === question.answer;

  return (
    <main>
      <h2>{question.text}</h2>
      <div className="options">
        {question.options.map((option, i) => (
          // 2. Disable the buttons once an answer is picked
          <button key={option} id={`opt-${i}`} onClick={() => setPicked(option)} disabled={answered}>
            {option}
          </button>
        ))}
      </div>

      {/* 3. Feedback, only after answering */}
      {answered && (
        <p className={correct ? "feedback right" : "feedback wrong"}>
          {correct ? "Correct!" : `Not quite. The answer is ${question.answer}.`}
        </p>
      )}

      {/* 4. The Try again button, only after a wrong answer */}
      {answered && !correct && (
        <button id="retry" onClick={() => setPicked(null)}>
          Try again
        </button>
      )}
    </main>
  );
}

