import { useState } from "react";
import "./App.css";

export default function App() {
  // 1. State for each field, 3. for the error message, 4. for the roster
  const [player, setPlayer] = useState("");
  const [team, setTeam] = useState("Red");
  const [error, setError] = useState("");
  const [roster, setRoster] = useState([]);

  function handleSubmit(event) {
    // 2–4. Stop the reload, check the name, then add the player and reset the form
    event.preventDefault();
    const name = player.trim();
    if (name === "") {
      setError("Please enter a name.");
      return;
    }
    setRoster([...roster, { id: roster.length + 1, name, team }]);
    setError("");
    setPlayer("");
  }

  return (
    <main>
      <h1>Join a team</h1>
      <form onSubmit={handleSubmit}>
        <label htmlFor="player">Name</label>
        <input id="player" value={player} onChange={(e) => setPlayer(e.target.value)} />

        <label htmlFor="team">Team</label>
        <select id="team" value={team} onChange={(e) => setTeam(e.target.value)}>
          <option value="Red">Red</option>
          <option value="Blue">Blue</option>
          <option value="Green">Green</option>
        </select>

        <button id="join">Join</button>
      </form>
      {/* 3. The error message goes here, only when there is one */}
      {error && <p className="error" role="alert">{error}</p>}
      <ul id="roster">
        {roster.map((p) => (
          <li key={p.id}>
            {p.name} ({p.team})
          </li>
        ))}
      </ul>
    </main>
  );
}

