import { useEffect, useState } from "react";
import "./App.css";

const API = "https://api.codegrove.test";

export default function App() {
  const [pets, setPets] = useState([]);
  // 1. Track the request: "loading", "ready" or "error"
  const [status, setStatus] = useState("loading");

  // 1. Load /pets once, when the component appears.
  //    Check response.ok; on any failure set status to "error".
  useEffect(() => {
    let ignore = false; // set when the component goes away before the answer arrives

    fetch(`${API}/pets`)
      .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
      })
      .then((data) => {
        if (ignore) return;
        setPets(data);
        setStatus("ready");
      })
      .catch(() => {
        if (!ignore) setStatus("error");
      });

    return () => {
      ignore = true;
    };
  }, []);

  // 2. Only pets that haven't been adopted
  const available = pets.filter((pet) => !pet.adopted);

  // 3. Loading and error screens (early returns)
  if (status === "loading") return <p id="status">Loading pets…</p>;
  if (status === "error") return <p id="status">Couldn't load the pets. Try again later.</p>;

  return (
    <main>
      <h1>Adopt a friend</h1>
      <ul id="pets">
        {available.map((pet) => (
          <li key={pet.id}>
            {pet.name} the {pet.species} ({pet.age})
          </li>
        ))}
      </ul>
    </main>
  );
}

