import { useState } from "react";
import "./App.css";
import { products } from "./products";
import ProductList from "./ProductList";
import CartSummary from "./CartSummary";

export default function App() {
  // 1. The cart lives here: an object of { productId: quantity }, like { 1: 2, 3: 1 }
  const [cart, setCart] = useState({});

  // 2. A function that adds one of a product to the cart (without mutating it)
  function addToCart(id) {
    setCart((current) => ({ ...current, [id]: (current[id] ?? 0) + 1 }));
  }

  return (
    <main>
      <h1>Merch shop</h1>
      {/* 3. Pass what each child needs */}
      <ProductList products={products} cart={cart} onAdd={addToCart} />
      <CartSummary products={products} cart={cart} />
    </main>
  );
}

