    const quantity = cart[product.id] ?? 0;
    items += quantity;
    total += quantity * product.price;
  }

  return (
    <aside>
      <p id="cart-count">{items} items</p>
      <p id="cart-total">Total: ${total.toFixed(2)}</p>
    </aside>
  );
}

