    event.preventDefault();
    if (text.trim() === "") return; // ignore empty wishes
    setWishes([...wishes, { id: nextId, text: text.trim() }]);
    setNextId(nextId + 1);
    setText("");
  }

  function remove(id) {
    setWishes(wishes.filter((wish) => wish.id !== id));
  }

  return (
    <main>
      <h1>🎁 My Wish List</h1>
      <form onSubmit={handleSubmit}>
        <input id="wish" placeholder="I wish for…" value={text} onChange={(event) => setText(event.target.value)} />
        <button id="add">Add</button>
      </form>
      <h2>{wishes.length} wishes</h2>
      {wishes.length === 0 && <p className="empty">Your wish list is empty.</p>}
      <ul id="wishes">
        {wishes.map((wish) => (
          <li key={wish.id}>
            {wish.text} <button onClick={() => remove(wish.id)}>Remove</button>
          </li>
        ))}
      </ul>
    </main>
  );
}

