import { useState } from "react";
import "./App.css";
import TaskForm from "./TaskForm";
import TaskItem from "./TaskItem";

// 4. The three filters. Each has a label and a test for which tasks it shows.
const FILTERS = {
  all: { label: "All", test: () => true },
  active: { label: "Active", test: (task) => !task.done },
  done: { label: "Done", test: (task) => task.done },
};

export default function App() {
  // 3. State: the tasks, and which filter is picked
  const [tasks, setTasks] = useState([]);
  const [filter, setFilter] = useState("all");

  // 3. Add a task, toggle a task, clear done tasks
  function addTask(title) {
    setTasks((current) => [...current, { id: crypto.randomUUID(), title, done: false }]);
  }

  function toggleTask(id) {
    setTasks((current) => current.map((task) => (task.id === id ? { ...task, done: !task.done } : task)));
  }

  function clearDone() {
    setTasks((current) => current.filter((task) => !task.done));
  }

  // 4–5. Derived values: the visible tasks, and how many are left
  const visible = tasks.filter(FILTERS[filter].test);
  const left = tasks.filter((task) => !task.done).length;

  return (
    <main>
      <h1>✅ Task Tracker</h1>
      <TaskForm onAdd={addTask} />

      <nav aria-label="Filter tasks">
        {Object.entries(FILTERS).map(([key, { label }]) => (
          <button key={key} id={`filter-${key}`} aria-pressed={filter === key} onClick={() => setFilter(key)}>
            {label}
          </button>
        ))}
      </nav>

      <ul id="tasks">
        {visible.map((task) => (
          <TaskItem key={task.id} task={task} onToggle={toggleTask} />
        ))}
      </ul>

      <footer>
        <p id="left">
          {left} {left === 1 ? "task" : "tasks"} left
        </p>
        <button id="clear-done" onClick={clearDone} disabled={left === tasks.length}>
          Clear done
        </button>
      </footer>
    </main>
  );
}

